head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "options.useATagBtn(선택) 파라미터를 true 로 설정하면, options.type 속성값이 'browserPopup' 이 아닐때 닫기 버튼을 'a' 태그로 렌더링합니다.",
        "options.useATagBtn(선택) 파라미터를 false 로 설정하면, options.type 속성값이 'browserPopup' 이 아닐때 닫기 버튼을 'div' 태그로 렌더링합니다.",
        "options.useATagBtn(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
        "options.adaptiveFrame(선택) 파라미터를 true 로 설정하면, 팝업 내부 컴포넌트가 adaptive 속성을 가진 경우 부모 프레임의 크기에 따라 적응형 모드를 적용합니다.",
        "options.adaptiveFrame(선택) 파라미터를 false 로 설정하면, 팝업 내부 컴포넌트가 adaptive 속성을 가진 경우 브라우저 창의 크기에 따라 적응형 모드를 적용합니다.",
        "options.adaptiveFrame(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
        "options.adaptiveFrame(선택) 파라미터는 options.type 속성값이 'wframePopup' 인 경우에 적용됩니다.",
        "options.processMsgFrame(선택) 파라미터를 true 로 설정하면, options.type 속성값이 'wframePopup' 일때 'ProcessMessage' 레이어를 팝업 화면에만 제한적으로 표시합니다.",
        "options.processMsgFrame(선택) 파라미터를 false 로 설정하면, options.type 속성값이 'wframePopup' 일때 'ProcessMessage' 레이어를 팝업 화면에만 제한적으로 표시하지 않습니다.",
        "options.processMsgFrame(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    $c.gcm.createLabel('label="[전제] 팝업 너비 700px, resizable=true 고정. 팝업 안 표 영역은 adaptive=layout, adaptiveThreshold=600 입니다.\n[절차] adaptive : 팝업 오른쪽 아래 모서리를 드래그해 너비를 600px 이하로 줄인 뒤 팝업 안 adaptive 확인 버튼 클릭 (결과창에 팝업 너비·적용 여부 출력)\n[절차] ProcessMessage : 팝업 안 ProcessMessage 표시 버튼 클릭 (1초 표시 후 결과창에 차단 레이어 판정 출력)"', '', 'label1');

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.popupUrl = "/sample/common_link/p_openPopup_popup.xml";



scwin.out = function (str) {
    wf_body_bottom.getObj("scwin").setReturnValue(str);
};



// 이전 테스트 팝업 정리 (내부 팝업을 정리했으면 true 반환)
scwin.closeAllPopup = function () {
    let list = $p.getAllPopupList().slice();
    let closedInner = false;
    for (let i = 0; i < list.length; i++) {
        let pw = list[i].popupWin;
        try {
            if (pw && typeof pw.forceClose === "function") {
                pw.forceClose();
                closedInner = true;
            } else if (pw && typeof pw.close === "function") {
                pw.close();
            }
        } catch (e) {}
    }
    return closedInner;
};



// 이전 팝업 정리 후 openPopup 실행
// (내부 팝업 정리는 비동기로 끝나므로 300ms 후 연다. 클릭 직후 5초 이내라 browserPopup 도 사용자 동작으로 처리됨)
scwin.runOpenPopup = function (optionList, callback, delay) {
    let fn = function () {
        for (let i = 0; i < optionList.length; i++) {
            $p.openPopup(scwin.popupUrl, optionList[i]);
        }
        if (callback) setTimeout(callback, delay || 1500);
    };
    if (scwin.closeAllPopup()) {
        setTimeout(fn, 300);
    } else {
        fn();
    }
};



// options.id 로 팝업 정보 조회 (Page Scope 적용 시 실행 ID 는 'mf_' 접두사가 붙음)
scwin.findPopup = function (id) {
    let list = $p.getAllPopupList();
    for (let i = list.length - 1; i >= 0; i--) {
        if ((list[i].options.org_id === id || list[i].options.id === id) && list[i].popupWin) return list[i];
    }
    return null;
};



// options.id 로 팝업 최상위 div 조회
scwin.popupEl = function (id) {
    return document.querySelector(".w2popup_window[id$='" + id + "']");
};



// 팝업 내부 요소(타이틀바 버튼 등) 조회
scwin.popupPart = function (id, suffix) {
    let el = scwin.popupEl(id);
    return el ? document.getElementById(el.id + "_" + suffix) : null;
};



scwin.rectStr = function (el) {
    let r = el.getBoundingClientRect();
    return "left " + Math.round(r.left + window.scrollX) + ", top " + Math.round(r.top + window.scrollY) + " / 크기 : " + Math.round(r.width) + " x " + Math.round(r.height);
};

scwin.btn_openPopup_onclick = function () {
    let type = par_type.getValue();
    let useATagBtn = par_useATagBtn.getValue();
    let adaptiveFrame = par_adaptiveFrame.getValue();
    let processMsgFrame = par_processMsgFrame.getValue();

    let options = { id: "popup_1", type: type, left: "100px", top: "100px", width: "700px", height: "380px", popupName: "openPopup 팝업", resizable: true };
    if (useATagBtn !== "") options.useATagBtn = (useATagBtn === "true");
    if (adaptiveFrame !== "") options.adaptiveFrame = (adaptiveFrame === "true");
    if (processMsgFrame !== "") options.processMsgFrame = (processMsgFrame === "true");

    scwin.runOpenPopup([options], scwin.printResult);
};



// validation 1~3 판정 출력 (닫기 버튼 태그)
scwin.printResult = function () {
    let closeBtn = scwin.popupPart("popup_1", "close");
    scwin.out("닫기 버튼 태그 : " + (closeBtn ? closeBtn.tagName.toLowerCase() : "없음"));
    scwin.bindPopupClick();
};



// 팝업 안 'adaptive 확인'·'ProcessMessage 표시' 버튼 클릭을 감지 (wframePopup=부모 document, iframePopup=iframe document)
// 같은 함수 참조라 부모 document 에는 한 번만 등록된다
scwin.bindPopupClick = function () {
    document.addEventListener("click", scwin.onPopupClick);
    let el = scwin.popupEl("popup_1");
    let ifr = el ? el.querySelector("iframe") : null;
    if (!ifr) return;
    let bind = function () {
        try { ifr.contentDocument.addEventListener("click", scwin.onPopupClick); } catch (e) {}
    };
    bind();
    ifr.addEventListener("load", bind);
};



scwin.onPopupClick = function (e) {
    let btn = e.target.closest ? e.target.closest("[id$='_btn_adaptive'], [id$='_btn_processMsg']") : null;
    if (!btn) return;
    if (/_btn_adaptive$/.test(btn.id)) {
        scwin.printAdaptive(btn);
    } else {
        // 팝업 화면이 ProcessMessage 를 1초 표시하므로 표시 중(500ms)에 판정하고, 숨겨진 뒤 출력한다
        let ret;
        setTimeout(function () { ret = scwin.checkProcessMsg(); }, 500);
        setTimeout(function () { scwin.out(ret); }, 1300);
    }
};



// validation 4~7 판정 출력 (팝업 너비 / 팝업 안 adaptive 레이아웃 적용 여부)
scwin.printAdaptive = function (btn) {
    let grp = btn.ownerDocument.getElementById(btn.id.replace(/btn_adaptive$/, "grp_adaptive"));
    let el = scwin.popupEl("popup_1");
    scwin.out("팝업 너비 : " + (el ? Math.round(el.getBoundingClientRect().width) : "없음") + " / adaptive 레이아웃 적용 : " + (!!grp && grp.classList.contains("w2tb_adaptive_layout")));
};



scwin.rectArr = function (el) {
    let r = el.getBoundingClientRect();
    return [r.left, r.top, r.width, r.height].map(Math.round).join(",");
};



scwin.visible = function (el) {
    if (!el) return false;
    let r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0;
};



// validation 8~10 판정 (차단 레이어가 팝업 wframe 영역인지 / 화면 전체인지 / 팝업 밖 부모 openPopup 버튼을 가리는지)
scwin.checkProcessMsg = function () {
    let el = scwin.popupEl("popup_1");
    let wframe = el ? document.getElementById(el.id + "_wframe") : null;
    let frameModal = wframe ? wframe.querySelector(".w2_proc_modal") : null;
    let pageModal = document.querySelector("[id^='___processbar'].w2modal");
    let inFrame = scwin.visible(frameModal) && scwin.rectArr(frameModal) === scwin.rectArr(wframe);
    let full = scwin.visible(pageModal) && scwin.rectArr(pageModal) === [0, 0, window.innerWidth, window.innerHeight].join(",");
    let btn = document.querySelector("[id$='btn_openPopup']");
    let r = btn.getBoundingClientRect();
    let hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    return "차단 레이어 = 팝업 wframe 영역 : " + inFrame + " / 차단 레이어 = 화면 전체 : " + full + " / 부모 openPopup 버튼 가림 : " + !btn.contains(hit);
};
